// oxlint-disable-next-line import/no-nodejs-modules -- Native fixtures read the committed source assets and own a scratch cache.
import fs from 'node:fs';
// oxlint-disable-next-line import/no-nodejs-modules -- These fixture programs run from the repository root.
import { resolve } from 'node:path';
import { generate } from '../../src/shards/_template/shard.config';
import { createProjectGeneration } from '../../src/sharddev/projectGeneration';
import { compileDeclaredDecisionScripts as compileDecisionScripts } from '../../src/sharddev/buildDecisionScripts';
import { compileTemplateBoss, TEMPLATE_BOSS_INPUTS } from '../../src/shards/_template/generators/boss';
import { compileScript } from '../../src/sharddev/bake/compileScript';
import { compileTemplateBehaviour, TEMPLATE_BEHAVIOUR_INPUTS, templateBehaviourMetadata } from '../../src/shards/_template/generators/behaviour';
import { hashImmutableBytes } from '../../src/sharddev/immutable';

const project = resolve(import.meta.dirname, '../../src/shards/_template');
const scripts = await compileTemplateBehaviour({ compileScript }, new Map(TEMPLATE_BEHAVIOUR_INPUTS.map(file => [file, new Uint8Array(fs.readFileSync(resolve(project, file)))])));
const bossBytes = await compileTemplateBoss({ compileDecisionScripts }, new Map(TEMPLATE_BOSS_INPUTS.map(file => [file, new Uint8Array(fs.readFileSync(resolve(project, file)))])));
export const TEMPLATE_BOSS = { hash: hashImmutableBytes(bossBytes), compressed: bossBytes.length };
export const TEMPLATE_BEHAVIOUR = templateBehaviourMetadata(scripts);
// SHARD-SOURCE AP36c: the Template's own build (shard.config.ts, scene source plus its rows), with its generated bytes
fs.mkdirSync(resolve('tmp'), { recursive: true });
const cache = fs.mkdtempSync(resolve('tmp', 'template-source-')), generated = new Map<string, Uint8Array>();
const built = await generate(createProjectGeneration(project, 'c'.repeat(64), generated, cache)).finally(() => { fs.rmSync(cache, { recursive: true, force: true }); });
/** Native tests consume the same rows and bytes as the executable build entry. */
export const TEMPLATE_SOURCE = built.shard;
/** Preserve independently owned input bytes for each admission. */
export function templateAssets(hashes?: ReadonlySet<string>): Map<string, Uint8Array> {
  const available = new Map([...TEMPLATE_SOURCE.files, TEMPLATE_BOSS].map(file => [file.hash, file]));
  const selected = hashes === undefined ? TEMPLATE_SOURCE.files : [...hashes].map(hash => available.get(hash));
  if (selected.some(file => file === undefined)) throw new Error('Unknown Template fixture asset');
  return new Map(selected.map(file => {
    if (file === undefined) throw new Error('Unknown Template fixture asset');
    return [file.hash, new Uint8Array(generated.get(file.hash) ?? fs.readFileSync(resolve(project, 'assets', file.hash)))];
  }));
}
